import sys
from bisect import bisect_right

data = sys.stdin.read().split()
n = int(data[0])
s = int(data[1])
low = [int(data[2 + 2 * i]) for i in range(n)]
high = [int(data[3 + 2 * i]) for i in range(n)]
if n <= 1500:
    # exhaustive: test every pair against the definition
    total = 0
    for i in range(n):
        for j in range(i + 1, n):
            if low[i] + low[j] <= s <= high[i] + high[j]:
                total += 1
    print(total)
else:
    # same two counts, taken by binary search instead of a sweep
    def count_le(arr, limit):
        b = sorted(arr)
        total = 0
        for v in b:
            total += bisect_right(b, limit - v)
            if v + v <= limit:
                total -= 1
        return total // 2

    print(count_le(low, s) - count_le(high, s - 1))
